import { EventEmitter } from "events";
import net from "net";
import data from "./../package.json" with { type: "json" };

async function getIPC(startId = 0, maxId = 10) {
  const isWin = process.platform === "win32";
  const prefix =
    process.env.XDG_RUNTIME_DIR ||
    process.env.TMPDIR ||
    process.env.TMP ||
    process.env.TEMP ||
    "/tmp";
  for (let id = startId; id <= maxId; id++) {
    const path = isWin
      ? `\\\\?\\pipe\\discord-ipc-${id}`
      : `${prefix.replace(/\/$/, "")}/discord-ipc-${id}`;
    try {
      return await new Promise((res, rej) => {
        const sock = net.createConnection({ path });
        sock.once("connect", () => res(sock));
        sock.once("error", () => (sock.destroy(), rej()));
      });
    } catch {}
  }
  throw new Error("Could not connect");
}
function encode(OPCode, data) {
  const json = JSON.stringify(data);
  const length = Buffer.byteLength(json, "utf8");
  const buffer = Buffer.alloc(8 + length);
  buffer.writeInt32LE(OPCode, 0);
  buffer.writeInt32LE(length, 4);
  buffer.write(json, 8, length, "utf8");
  return buffer;
}
function decode(buffer) {
  const OPCode = buffer.readInt32LE(0);
  const length = buffer.readInt32LE(4);
  const json = buffer.toString("utf8", 8, 8 + length);
  const data = JSON.parse(json);
  return { OPCode, data };
}
function createChunkDecoder() {
  let buffer = Buffer.alloc(0);
  return async function decodeNext(socket) {
    while (true) {
      let chunk;
      while ((chunk = socket.read()) !== null) {
        buffer = Buffer.concat([buffer, chunk]);
      }
      if (buffer.length >= 8) {
        const length = buffer.readInt32LE(4);
        if (buffer.length >= 8 + length) {
          const packet = buffer.slice(0, 8 + length);
          buffer = buffer.slice(8 + length);
          return decode(packet);
        }
      }
      await new Promise((resolve) => socket.once("readable", resolve));
    }
  };
}

const version = data.version;
const OPCodes = Object.freeze({
  Handshake: 0,
  Frame: 1,
  Close: 2,
  Ping: 3,
  Pong: 4,
});

class Client extends EventEmitter {
  constructor() {
    super();
    this.clientId = null;
    this.user = null;
    this.connected = false;
    this.socket = null;
  }

  /**
   * Used to connect to Discord.
   * @param {string} clientId Application client ID.
   * @returns {Promise<Client>}
   */
  async login(clientId) {
    this.clientId = clientId;
    this.socket = await getIPC();
    this.socket.pause();
    const decodeChunk = createChunkDecoder();
    this.socket.on("readable", async () => {
      const packet = await decodeChunk(this.socket);
      switch (packet.OPCode) {
        case OPCodes.Frame:
          if (packet.data.evt === "READY") {
            this.connected = true;
            this.user = packet.data.data.user;
            this.emit("ready", packet);
          }
          break;
        default:
          break;
      }
    });
    this.socket.on("error", (err) => {
      this.emit("error", err);
    });
    this.socket.on("close", () => {
      this.connected = false;
      this.emit("close");
    });
    this.#send(OPCodes.Handshake, {
      v: 1,
      client_id: clientId,
    });
    return this;
  }

  /**
   * Destroy the client.
   * @returns {Promise}
   */
  destroy() {
    if (!this.socket) return Promise.resolve();
    return new Promise((resolve) => {
      this.socket.once("close", () => {
        this.connected = false;
        this.socket = null;
        resolve();
      });
      this.socket.end();
      this.socket.destroy();
    });
  }

  /**
   * Used to update a user's Rich Presence.
   * @param {Object} activity Options.
   * @param {number} [pid] The process ID. Defaults to the executing process' PID.
   * @see https://docs.discord.com/developers/events/gateway-events#activity-object
   * @returns {Promise<boolean>}
   */
  setActivity(activity, pid) {
    if (!this.socket || !this.connected) throw new Error("Client is not connected");
    return this.#send(OPCodes.Frame, {
      cmd: "SET_ACTIVITY",
      args: {
        pid: pid || process.pid,
        activity,
      },
      nonce: Math.random().toString(36).slice(2),
    });
  }

  /**
   * Used to clear a user's Rich Presence.
   * @param {number} [pid] The process ID. Defaults to the executing process' PID.
   * @returns {Promise<boolean>}
   */
  clearActivity(pid) {
    return this.setActivity(null, pid);
  }

  #send(OPCode, data) {
    return this.socket.write(encode(OPCode, data));
  }
}

export { version, Client };
export default {
  version,
  Client,
};
